begin;
create extension if not exists pgtap with schema extensions;
select plan(8);
insert into auth.users(id,email) values('93939393-9393-4393-8393-939393939393','snapshot-controller@fleet.test');
insert into tenants(id,name,code) values('11111111-1111-4111-8111-111111111118','Snapshot own','SNAP'),('11111111-1111-4111-8111-111111111117','Snapshot foreign','FOREIGN');
insert into memberships values('11111111-1111-4111-8111-111111111118','93939393-9393-4393-8393-939393939393','controller');
insert into vehicles(id,tenant_id,fleet_no,horse_reg) values('22222222-2222-4222-8222-222222222228','11111111-1111-4111-8111-111111111118','SNAP-1','CA SNAP');
create function pg_temp.payload() returns jsonb language sql as $$select jsonb_build_object('idempotency_key','44444444-4444-4444-8444-444444444448','tenant_id','11111111-1111-4111-8111-111111111118','vehicle_id','22222222-2222-4222-8222-222222222228','cargo','Goods','loading_code','CPT','loading_customer','Collection','delivery_code','DBN','delivery_customer','Delivery','scheduled_at',now()+interval '1 day','loading_lat',-33,'loading_lng',18,'destination_lat',-29,'destination_lng',31);$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','93939393-9393-4393-8393-939393939393',true);
select is(create_transport_job(pg_temp.payload()),create_transport_job(pg_temp.payload()),'same request key returns same job');
select is((select count(*)::int from visible_jobs),1,'replay creates only one job');
select throws_ok($$select create_transport_job(pg_temp.payload()||'{"cargo":"Different"}')$$,'40001',null,'changed payload cannot reuse request key');
select throws_ok($$select create_transport_job(pg_temp.payload()||'{"tenant_id":"11111111-1111-4111-8111-111111111117"}')$$,'42501',null,'idempotency cannot cross tenant boundary');
select is(jsonb_array_length(workspace_snapshot()->'tenants'),1,'snapshot has only own tenant');
select is(workspace_snapshot()->'jobs'->0->>'eta','','missing ETA normalised for UI');
select is(workspace_snapshot()->>'role','controller','snapshot carries scoped capability');
reset role;set local role anon;
select throws_ok($$select workspace_snapshot()$$,'42501',null,'anonymous snapshot denied');
select * from finish();rollback;
